import pandas as pd

def valid_serial_products(products: pd.DataFrame) -> pd.DataFrame:
    pat = r'(?<![0-9])SN[0-9]{4}-[0-9]{4}(?![0-9])'
    mask = products['description'].str.contains(pat, regex=True)
    return products[mask].sort_values('product_id')

