#include <regex>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<vector<string>> validSerialProducts(vector<vector<string>>& products) {
        regex pat("(^|[^0-9])SN[0-9]{4}-[0-9]{4}($|[^0-9])");
        vector<vector<string>> res;
        for (auto& p : products)
            if (regex_search(p[2], pat)) res.push_back(p);
        sort(res.begin(), res.end(), [](auto& a, auto& b){ return stoi(a[0]) < stoi(b[0]); });
        return res;
    }
};

c.java:
import java.util.*;

class Solution {
    public List<List<String>> validSerialProducts(List<List<String>> products) {
        String pat = ".*[^0-9]?SN[0-9]{4}-[0-9]{4}([^0-9]|$).*";
        List<List<String>> res = new ArrayList<>();
        for (List<String> p : products)
            if (p.get(2).matches(pat)) res.add(p);
        res.sort(Comparator.comparingInt(a -> Integer.parseInt(a.get(0))));
        return res;
    }
}

